com.mirth.connect.plugins.javascriptstep.script:
var rawMessage = connectorMessage.getRawData();

var MessageDigest =
    Packages.java.security.MessageDigest;

var StandardCharsets =
    Packages.java.nio.charset.StandardCharsets;

var digest =
    MessageDigest.getInstance("SHA-256");

var hashBytes = digest.digest(
    new java.lang.String(rawMessage)
        .getBytes(StandardCharsets.UTF_8)
);

var hex = new java.lang.StringBuilder();

for (var i = 0; i < hashBytes.length; i++) {
    var value = hashBytes[i] & 0xff;

    if (value < 16) {
        hex.append("0");
    }

    hex.append(
        java.lang.Integer.toHexString(value)
    );
}

channelMap.put(
    "audit_payload_sha256",
    hex.toString()
);

/* LAB_OML_O21_IN source validation */
var failures = [];
function safeValue(node) {
    try { return node == null ? "" : String(node.toString()).trim(); }
    catch (e) { return ""; }
}
var messageCode = safeValue(msg['MSH']['MSH.9']['MSH.9.1']);
var triggerEvent = safeValue(msg['MSH']['MSH.9']['MSH.9.2']);
var structure = safeValue(msg['MSH']['MSH.9']['MSH.9.3']);
var receivingApplication = safeValue(msg['MSH']['MSH.5']['MSH.5.1']);
var receivingFacility = safeValue(msg['MSH']['MSH.6']['MSH.6.1']);
var patientId = safeValue(msg['PID']['PID.3']['PID.3.1']);
var patientFamily = safeValue(msg['PID']['PID.5']['PID.5.1']);
var patientGiven = safeValue(msg['PID']['PID.5']['PID.5.2']);
var patientDob = safeValue(msg['PID']['PID.7']['PID.7.1']);
var patientSex = safeValue(msg['PID']['PID.8']['PID.8.1']);
var assigningAuthority = safeValue(msg['PID']['PID.3']['PID.3.4']);
var identifierType = safeValue(msg['PID']['PID.3']['PID.3.5']);
var visitNumber = safeValue(msg['PV1']['PV1.19']['PV1.19.1']);
var orderControl = safeValue(msg['ORC']['ORC.1']['ORC.1.1']);
var orcPlacer = safeValue(msg['ORC']['ORC.2']['ORC.2.1']);
var obrPlacer = safeValue(msg['OBR']['OBR.2']['OBR.2.1']);
var serviceCode = safeValue(msg['OBR']['OBR.4']['OBR.4.1']);
var serviceText = safeValue(msg['OBR']['OBR.4']['OBR.4.2']);
var codingSystem = safeValue(msg['OBR']['OBR.4']['OBR.4.3']);

if (messageCode != 'OML') failures.push('MSH-9.1 must be OML');
if (triggerEvent != 'O21') failures.push('MSH-9.2 must be O21');
if (structure != 'OML_O21') failures.push('MSH-9.3 must be OML_O21');
if (receivingApplication != 'SYNLIS') failures.push('MSH-5 must be SYNLIS');
if (receivingFacility != 'LAB') failures.push('MSH-6 must be LAB');
if (!patientId) failures.push('PID-3 patient identifier is required');
if (!patientFamily) failures.push('PID-5.1 family name is required');
if (!patientGiven) failures.push('PID-5.2 given name is required');
if (!/^\d{8}$/.test(patientDob)) failures.push('PID-7 must be YYYYMMDD');
if (!/^[FMU]$/.test(patientSex)) failures.push('PID-8 must be F, M, or U');
if (assigningAuthority != 'INTEROPLAB') failures.push('PID-3.4 must be INTEROPLAB');
if (identifierType != 'MR') failures.push('PID-3.5 must be MR');
if (!visitNumber) failures.push('PV1-19 visit number is required');
if (orderControl != 'NW') failures.push('ORC-1 must be NW');
if (!orcPlacer) failures.push('ORC-2 placer order number is required');
if (orcPlacer != obrPlacer) failures.push('ORC-2 and OBR-2 must match');
if (!serviceCode) failures.push('OBR-4.1 service code is required');
if (!serviceText) failures.push('OBR-4.2 service text is required');
if (codingSystem != 'LN') failures.push('OBR-4.3 must be LN');

channelMap.put('oml_patient_identifier', patientId);
channelMap.put('oml_patient_family_name', patientFamily);
channelMap.put('oml_patient_given_name', patientGiven);
channelMap.put('oml_patient_date_of_birth', patientDob);
channelMap.put('oml_patient_administrative_sex', patientSex);
channelMap.put('oml_visit_number', visitNumber);
channelMap.put('oml_order_control', orderControl);
channelMap.put('oml_placer_order_number', orcPlacer);
channelMap.put('oml_service_code', serviceCode);
channelMap.put('oml_service_text', serviceText);
channelMap.put('oml_service_coding_system', codingSystem);
channelMap.put('validation_failure_reason', failures.join('; '));
channelMap.put('validation_failure_category', 'INTERFACE_CONTRACT');
channelMap.put('validation_status', failures.length == 0 ? 'PASS' : 'FAIL');

properties.query:
var dbConn = null;

try {
    /*
     * Obtain interoperability database configuration from
     * the Mirth container environment.
     */
    var dbUrl = java.lang.System.getenv("INTEROP_DB_URL");
    var dbUser = java.lang.System.getenv("INTEROP_DB_USER");
    var dbPassword = java.lang.System.getenv("INTEROP_DB_PASSWORD");

    if (dbUrl == null || dbUser == null || dbPassword == null) {
        throw new Error(
            "Required INTEROP_DB_* environment configuration is missing."
        );
    }


    /*
     * Open the interoperability audit database connection.
     */
    dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        "org.postgresql.Driver",
        dbUrl,
        dbUser,
        dbPassword
    );


    /*
     * PostgreSQL remains authoritative for transaction
     * classification.
     *
     * The function will return:
     *
     *   recorded_audit_id
     *   logical_transaction_id
     *   classified_outcome
     *
     * classified_outcome will be one of:
     *
     *   FIRST_DELIVERY
     *   EXACT_REPLAY
     *   CONFLICTING_REUSE
     */
    var sql =
        "SELECT " +
        "recorded_audit_id, " +
        "logical_transaction_id, " +
        "classified_outcome " +
        "FROM audit.record_interface_receipt(" +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR)" +
        ")";


    /*
     * Bind the values rather than concatenating HL7 content
     * directly into the SQL statement.
     */
    var parameters = new java.util.ArrayList();

    parameters.add(
        channelMap.get("audit_message_control_id")
    );

    parameters.add(
        channelMap.get("audit_message_type")
    );

    parameters.add(
        channelMap.get("audit_trigger_event")
    );

    parameters.add(
        channelMap.get("audit_patient_identifier")
    );

    parameters.add(
        channelMap.get("audit_sending_application")
    );

    parameters.add(
        channelMap.get("audit_sending_facility")
    );

    parameters.add(
        channelMap.get("audit_payload_sha256")
    );


    /*
     * Execute PostgreSQL's classifier and capture its
     * returned row.
     */
    var result = dbConn.executeCachedQuery(
        sql,
        parameters
    );


    if (!result.next()) {
        throw new Error(
            "record_interface_receipt returned no classification result."
        );
    }


    var recordedAuditId =
        result.getString("recorded_audit_id");

    var logicalTransactionId =
        result.getString("logical_transaction_id");

    var classifiedOutcome =
        result.getString("classified_outcome");


    if (classifiedOutcome == null) {
        throw new Error(
            "record_interface_receipt returned a null classification."
        );
    }


    /*
     * Make PostgreSQL's authoritative result available
     * to the remainder of this Mirth message lifecycle.
     */
    channelMap.put(
        "audit_recorded_audit_id",
        java.lang.String.valueOf(recordedAuditId)
    );

    channelMap.put(
        "audit_logical_transaction_id",
        java.lang.String.valueOf(logicalTransactionId)
    );

    channelMap.put(
        "audit_attempt_outcome",
        classifiedOutcome
    );


    /*
     * Temporary validation logging.
     *
     * No database password is logged.
     */
    logger.info(
        "HL7 audit classification: outcome=" +
        classifiedOutcome +
        ", transaction_id=" +
        logicalTransactionId +
        ", audit_id=" +
        recordedAuditId
    );

}
finally {
    if (dbConn != null) {
        dbConn.close();
    }
}

/* Persist accepted OML into synthetic LIS-owned state. */
var dbConn = null;
try {
    if (String(channelMap.get('validation_status')) != 'PASS') return;
    var outcome = String(channelMap.get('audit_attempt_outcome'));
    if (outcome == 'CONFLICTING_REUSE') return;
    if (outcome != 'FIRST_DELIVERY' && outcome != 'EXACT_REPLAY') {
        throw new Error('Unexpected OML transaction classification: ' + outcome);
    }
    var dbUrl = java.lang.System.getenv('INTEROP_DB_URL');
    var dbUser = java.lang.System.getenv('INTEROP_DB_USER');
    var dbPassword = java.lang.System.getenv('INTEROP_DB_PASSWORD');
    if (dbUrl == null || dbUser == null || dbPassword == null) {
        throw new Error('Required INTEROP_DB_* configuration is missing.');
    }
    dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        'org.postgresql.Driver', dbUrl, dbUser, dbPassword
    );
    var sql =
        'SELECT lis_order_id, filler_order_number, created ' +
        'FROM lis.accept_order(CAST(? AS BIGINT), ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)';
    var p = new java.util.ArrayList();
    p.add(String(channelMap.get('audit_logical_transaction_id')));
    p.add(channelMap.get('audit_message_control_id'));
    p.add(channelMap.get('oml_patient_identifier'));
    p.add(channelMap.get('oml_patient_family_name'));
    p.add(channelMap.get('oml_patient_given_name'));
    p.add(channelMap.get('oml_patient_date_of_birth'));
    p.add(channelMap.get('oml_patient_administrative_sex'));
    p.add(channelMap.get('oml_visit_number'));
    p.add(channelMap.get('oml_placer_order_number'));
    p.add(channelMap.get('oml_service_code'));
    p.add(channelMap.get('oml_service_text'));
    p.add(channelMap.get('oml_service_coding_system'));
    p.add(channelMap.get('oml_order_control'));
    p.add(String(connectorMessage.getRawData()));
    var result = dbConn.executeCachedQuery(sql, p);
    if (!result.next()) throw new Error('lis.accept_order returned no row.');
    channelMap.put('lis_order_id', result.getString('lis_order_id'));
    channelMap.put('lis_filler_order_number', result.getString('filler_order_number'));
    channelMap.put('lis_order_created', result.getString('created'));
} finally {
    if (dbConn != null) dbConn.close();
}

var dbConn = null;

try {
    /*
     * Obtain interoperability database configuration
     * from the Mirth container environment.
     */
    var dbUrl =
        java.lang.System.getenv("INTEROP_DB_URL");

    var dbUser =
        java.lang.System.getenv("INTEROP_DB_USER");

    var dbPassword =
        java.lang.System.getenv("INTEROP_DB_PASSWORD");

    if (
        dbUrl == null ||
        dbUser == null ||
        dbPassword == null
    ) {
        throw new Error(
            "Required INTEROP_DB_* environment configuration is missing."
        );
    }

    /*
     * Open interoperability audit database connection.
     */
    dbConn =
        DatabaseConnectionFactory.createDatabaseConnection(
            "org.postgresql.Driver",
            dbUrl,
            dbUser,
            dbPassword
        );

    /*
     * Persist rejected message as durable quarantine evidence.
     *
     * quarantine_status is not supplied here because PostgreSQL
     * assigns the default value QUARANTINED.
     */
    var sql =
        "INSERT INTO audit.quarantined_messages (" +
        "message_control_id, " +
        "message_type, " +
        "trigger_event, " +
        "patient_identifier, " +
        "sending_application, " +
        "sending_facility, " +
        "failure_category, " +
        "failure_reason, " +
        "payload_text, " +
        "payload_sha256" +
        ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

    var parameters =
        new java.util.ArrayList();

    parameters.add(
        channelMap.get("audit_message_control_id")
    );

    parameters.add(
        channelMap.get("audit_message_type")
    );

    parameters.add(
        channelMap.get("audit_trigger_event")
    );

    parameters.add(
        channelMap.get("audit_patient_identifier")
    );

    parameters.add(
        channelMap.get("audit_sending_application")
    );

    parameters.add(
        channelMap.get("audit_sending_facility")
    );

    parameters.add(
        channelMap.get("validation_failure_category")
    );

    parameters.add(
        channelMap.get("validation_failure_reason")
    );

    parameters.add(
        connectorMessage.getRawData()
    );

    parameters.add(
        channelMap.get("audit_payload_sha256")
    );

    dbConn.executeUpdate(
        sql,
        parameters
    );

    logger.info(
        "ADT quarantine persistence: " +
        "control_id=" +
        channelMap.get("audit_message_control_id") +
        ", category=" +
        channelMap.get("validation_failure_category") +
        ", status=QUARANTINED"
    );
}
catch (e) {
    logger.error(
        "ADT quarantine persistence failed: " +
        e
    );

    /*
     * Fail closed.
     *
     * If we cannot preserve the rejected transaction,
     * we cannot claim that it was safely contained.
     */
    throw e;
}
finally {
    if (dbConn != null) {
        dbConn.close();
    }
}

channel.postprocessingScript:
/*
 * LAB_OML_O21_IN postprocessor
 *
 * Translate validation state and authoritative transaction
 * classification into the application-level HL7 acknowledgment
 * returned to the sender.
 *
 * Policy:
 *
 * validation failure    -> AR
 * FIRST_DELIVERY        -> AA
 * EXACT_REPLAY          -> AA
 * CONFLICTING_REUSE     -> AR
 * destination failure   -> AE
 * unknown condition     -> AE
 */

var auditOutcome =
    channelMap.get("audit_attempt_outcome");

var validationStatus =
    channelMap.get("validation_status");

var validationFailureReason =
    channelMap.get("validation_failure_reason");


/*
 * Inspect destination connector status independently of
 * validation and transaction classification.
 *
 * This preserves important distinctions:
 *
 *     validation-policy rejection -> AR
 *     integrity-policy rejection  -> AR
 *     processing/infrastructure failure -> AE
 */

var connectorMessages =
    message.getConnectorMessages();

var destinationError = false;

var connectorIterator =
    connectorMessages.entrySet().iterator();

while (connectorIterator.hasNext()) {

    var connectorEntry =
        connectorIterator.next();

    var metadataId =
        String(connectorEntry.getKey());

    /*
     * Metadata ID 0 is the source connector.
     * Everything else is a destination.
     */
    if (metadataId != "0") {

        var destinationStatus =
            String(
                connectorEntry
                    .getValue()
                    .getStatus()
            );

        if (destinationStatus == "ERROR") {
            destinationError = true;
            break;
        }
    }
}


/*
 * Obtain the original HL7 message from the source connector.
 *
 * The postprocessor's "message" object represents the complete
 * processed Mirth message. Connector metadata ID 0 is the source.
 */

var sourceConnectorMessage =
    connectorMessages.get(0);

var rawMessage =
    String(
        sourceConnectorMessage.getRawData()
    );


/*
 * Locate and parse the original MSH segment.
 */

var rawSegments =
    rawMessage.split(/\r\n|\n|\r/);

var mshSegment = null;

for (var i = 0; i < rawSegments.length; i++) {

    if (rawSegments[i].indexOf("MSH|") == 0) {
        mshSegment = rawSegments[i];
        break;
    }
}


var mshFields =
    mshSegment != null
        ? mshSegment.split("|")
        : [];


/*
 * Original MSH positions after JavaScript split("|"):
 *
 * [0]  MSH
 * [1]  MSH-2 Encoding Characters
 * [2]  MSH-3 Sending Application
 * [3]  MSH-4 Sending Facility
 * [4]  MSH-5 Receiving Application
 * [5]  MSH-6 Receiving Facility
 * [6]  MSH-7 Message Date/Time
 * [8]  MSH-9 Message Type
 * [9]  MSH-10 Message Control ID
 * [10] MSH-11 Processing ID
 * [11] MSH-12 Version ID
 */

var encodingCharacters =
    mshFields.length > 1 &&
    mshFields[1]
        ? mshFields[1]
        : "^~\\&";


var originalSendingApplication =
    mshFields.length > 2 &&
    mshFields[2]
        ? mshFields[2]
        : String(
            channelMap.get(
                "audit_sending_application"
            )
        );


var originalSendingFacility =
    mshFields.length > 3 &&
    mshFields[3]
        ? mshFields[3]
        : String(
            channelMap.get(
                "audit_sending_facility"
            )
        );


var originalReceivingApplication =
    mshFields.length > 4 &&
    mshFields[4]
        ? mshFields[4]
        : "MIRTH";


var originalReceivingFacility =
    mshFields.length > 5 &&
    mshFields[5]
        ? mshFields[5]
        : "INTEROPLAB";


var originalControlId =
    mshFields.length > 9 &&
    mshFields[9]
        ? mshFields[9]
        : String(
            channelMap.get(
                "audit_message_control_id"
            )
        );


var processingId =
    mshFields.length > 10 &&
    mshFields[10]
        ? mshFields[10]
        : "P";


var versionId =
    mshFields.length > 11 &&
    mshFields[11]
        ? mshFields[11]
        : "2.5.1";


var triggerEvent =
    String(
        channelMap.get(
            "audit_trigger_event"
        )
    );


/*
 * Determine the application acknowledgment code.
 */

var ackCode;
var ackText;


/*
 * Validation failure takes precedence over transaction
 * classification because invalid messages do not enter the
 * normal transaction-classification path.
 */
if (validationStatus == "FAIL") {

    ackCode = "AR";

    ackText =
        "Message rejected: " +
        (
            validationFailureReason
                ? String(validationFailureReason)
                : "interface contract validation failed."
        );

}
else if (destinationError) {

    ackCode = "AE";

    ackText =
        "Message processing error.";

}
else if (auditOutcome == "FIRST_DELIVERY") {

    ackCode = "AA";

    ackText =
        "Message accepted.";

}
else if (auditOutcome == "EXACT_REPLAY") {

    ackCode = "AA";

    ackText =
        "Exact replay accepted.";

}
else if (auditOutcome == "CONFLICTING_REUSE") {

    ackCode = "AR";

    ackText =
        "Message rejected: conflicting message identity reuse.";

}
else {

    /*
     * Fail closed if validation/classification state is missing
     * or contains an unexpected value.
     */

    ackCode = "AE";

    ackText =
        "Unable to determine transaction classification.";
}


/*
 * The ACK itself needs its own MSH-10.
 *
 * It must not reuse the incoming message's MSH-10.
 */

var ackUuid =
    String(
        java.util.UUID.randomUUID()
    )
    .replace(/-/g, "")
    .substring(0, 16);

var ackControlId =
    "ACK" + ackUuid;


var timestamp =
    new java.text.SimpleDateFormat(
        "yyyyMMddHHmmss.SSS"
    ).format(
        new java.util.Date()
    );


/*
 * For an ADT^A04 the general acknowledgment message type is:
 *
 *     ACK^A04^ACK
 *
 * Swap original sender/receiver application and facility
 * values when constructing the response MSH.
 */

var ack =
    "MSH|" +
    encodingCharacters +
    "|" +
    originalReceivingApplication +
    "|" +
    originalReceivingFacility +
    "|" +
    originalSendingApplication +
    "|" +
    originalSendingFacility +
    "|" +
    timestamp +
    "||" +
    "ACK^" +
    triggerEvent +
    "^ACK|" +
    ackControlId +
    "|" +
    processingId +
    "|" +
    versionId +
    "\r" +

    "MSA|" +
    ackCode +
    "|" +
    originalControlId +
    "|" +
    ackText +
    "\r";


logger.info(
    "HL7 postprocessor ACK policy: " +
    "validation_status=" +
    validationStatus +
    ", outcome=" +
    auditOutcome +
    ", destination_error=" +
    destinationError +
    ", ack_code=" +
    ackCode +
    ", original_control_id=" +
    originalControlId
);


/*
 * Returning a String causes Mirth to store this response
 * under the Postprocessor response-map entry.
 */

return ack;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
